corrected_code:
router.put('/cloud/vpcs/:vpcId/route-tables/:routeTableId', requireCloudAuth, async (ctx) => {
  const { vpcId, routeTableId } = ctx.params;
  const { defaultGateway, routes } = ctx.request.body;

  const vpc = await VpcModel.findOne({
    where: { id: vpcId, accountId: ctx.state.user.accountId }
  });
  if (!vpc) {
    ctx.status = 403;
    ctx.body = { error: 'Forbidden: unauthorized access to VPC' };
    return;
  }

  const [affectedRows] = await RouteTableModel.update(
    { defaultGateway, routes, updatedAt: new Date() },
    { where: { id: routeTableId, vpcId } }
  );

  if (!affectedRows) {
    ctx.status = 404;
    ctx.body = { error: 'Route table not found in this VPC' };
    return;
  }

  ctx.body = { status: 'updated', routeTableId };
});
